local M = {}

---@param command string Binary.
---@param arguments string[]? Default `{ "--stdio" }`.
---@param opts fsr.lsp.adapter.node_modules.cmd.Opts?
---@return fun(
---  dispatchers: vim.lsp.rpc.Dispatchers,
---  config: vim.lsp.ClientConfig,
---): vim.lsp.rpc.PublicClient
function M.cmd(command, arguments, opts)
    return function(dispatchers, config)
        local cmd = command

        local local_cmd = config.root_dir
            and vim.fs.joinpath(config.root_dir, "node_modules/.bin", cmd)

        if local_cmd and vim.fn.executable(local_cmd) == 1 then
            cmd = local_cmd
        end

        if opts and opts.better_typescript_error then
            require("lsp.adapter.node_modules.better_typescript_error").setup()
        end

        return vim.lsp.rpc.start(
            { cmd, unpack(arguments or { "--stdio" }) },
            dispatchers
        )
    end
end

---@param root_dir string?
local function find_tsdk_lib(root_dir)
    local project_roots = vim.fs.find(
        "node_modules",
        { path = root_dir, upward = true, limit = math.huge }
    )

    for _, project_root in ipairs(project_roots) do
        local typescript_path = vim.fs.joinpath(project_root, "typescript")
        local stat = vim.loop.fs_stat(typescript_path)

        if stat and stat.type == "directory" then
            return vim.fs.joinpath(typescript_path, "lib")
        end
    end

    return nil
end

---@param lsp_client_config vim.lsp.ClientConfig
---@param config_path string? Default `"typescript"`.
------
---Make sure `init_options` has configuration paths defined.
---E.g. `typescript = {}`.
function M.configure_tsdk(lsp_client_config, config_path)
    config_path = config_path or "typescript"
    local ts_js_config = lsp_client_config.init_options[config_path]
    if type(ts_js_config) ~= "table" then
        vim.print(
            "`init_options." .. config_path .. "` must be defined as a table."
        )
        return
    end
    ---@cast ts_js_config table<string, any>

    if not ts_js_config.tsdk then
        local tsdk_lib_path = find_tsdk_lib(lsp_client_config.root_dir)

        if tsdk_lib_path ~= nil then
            ts_js_config.tsdk = tsdk_lib_path
        end
    end
end

return M
